const express=require('express'),{readFileSync:rf,writeFileSync:wf,existsSync:es,mkdirSync:ms}=require('fs'),path=require('path'),app=express(),CFG=process.env.HOME+'/.config/ccs/config.json',DIR=path.dirname(CFG);
app.use(express.json());
app.get('/api/providers',(r,s)=>{try{let c=JSON.parse(rf(CFG,'utf8'));s.json({current:c.current||'',providers:Object.keys(c.providers||{})})}catch(e){s.json({current:'',providers:[]})}});
app.post('/api/providers',(r,s)=>{let n=r.body; if(!n.name) return s.status(400).json({error:'name required'}); if(!es(DIR)) ms(DIR,{recursive:true}); let c=es(CFG)?JSON.parse(rf(CFG,'utf8')):{current:'',providers:{}}; c.providers[n.name]={url:n.url||'https://api.deepseek.com/v1',key:n.key,model:n.model||'deepseek-chat'}; wf(CFG,JSON.stringify(c,null,2)); s.json({ok:true,providers:Object.keys(c.providers)})});
app.post('/api/switch',(r,s)=>{let c=JSON.parse(rf(CFG,'utf8')),p=c.providers[r.body.provider]; if(!p) return s.status(404).json({error:'not found'}); c.current=r.body.provider; wf(CFG,JSON.stringify(c,null,2)); let d=process.env.HOME+'/.claude'; if(!es(d)) ms(d); wf(d+'/.env','ANTHROPIC_API_KEY='+p.key+'\nANTHROPIC_BASE_URL='+p.url); s.json({ok:true,current:r.body.provider})});
app.delete('/api/providers/:n',(r,s)=>{let c=JSON.parse(rf(CFG,'utf8')); delete c.providers[r.params.n]; if(c.current===r.params.n) c.current=''; wf(CFG,JSON.stringify(c,null,2)); s.json({ok:true})});
app.get('/api/status',(r,s)=>{let c=es(CFG)?JSON.parse(rf(CFG,'utf8')):{current:''}; s.json({current:c.current})});
app.listen(3099,function(){console.log('CC Switch Panel on :3099')});
